const BOOK_NAME = "MUD World Example";
const DEFAULT_LOC = "overworld:a1";
const DEAD_STATUSES = new Set(["dead", "departed", "gone", "removed"]);

function parseCellJson(raw) {
    if (typeof raw !== "string" || !raw.trim()) return null;
    try {
        const obj = JSON.parse(raw);
        if (!obj || typeof obj !== "object" || !obj.id) return null;
        return {
            id: String(obj.id),
            map: String(obj.map || "overworld"),
            x: Number.isFinite(Number(obj.x)) ? Number(obj.x) : 0,
            y: Number.isFinite(Number(obj.y)) ? Number(obj.y) : 0,
            name: String(obj.name || obj.id),
            desc: (obj.desc && typeof obj.desc === "object") ? obj.desc : { day: String(obj.desc || ""), night: String(obj.desc || "") },
            exits: (obj.exits && typeof obj.exits === "object") ? obj.exits : {},
            objects: (obj.objects && typeof obj.objects === "object") ? obj.objects : {},
            npcs: (obj.npcs && typeof obj.npcs === "object") ? obj.npcs : {},
            images: (obj.images && typeof obj.images === "object") ? obj.images : {}
        };
    } catch (e) {
        return null;
    }
}

function loadWorld() {
    const cells = {};
    const lb = context.lorebook ? context.lorebook.get(BOOK_NAME) : null;
    if (lb) {
        const entries = lb.entries() || [];
        for (const entry of entries) {
            const cell = parseCellJson(entry.content);
            if (cell) {
                cells[cell.id] = cell;
            } else {
                console.log("MUD World Engine: skipped invalid JSON entry '" + (entry.name || "") + "'");
            }
        }
        if (Object.keys(cells).length > 0) {
            context.chat_data.set("mud_world_cache", cells);
        }
        return { cells, bookFound: true };
    }
    const cached = context.chat_data.get("mud_world_cache");
    if (cached && typeof cached === "object" && Object.keys(cached).length > 0) {
        return { cells: cached, bookFound: true };
    }
    return { cells: {}, bookFound: false };
}

function getDelta(loc) {
    const raw = context.chat_data.get("cell:" + loc);
    const d = (raw && typeof raw === "object") ? raw : {};
    return {
        events: Array.isArray(d.events) ? d.events : [],
        npcs: (d.npcs && typeof d.npcs === "object") ? d.npcs : {},
        objects: (d.objects && typeof d.objects === "object") ? d.objects : {},
        flags: (d.flags && typeof d.flags === "object") ? d.flags : {}
    };
}

function buildAsciiMap(cells, currentCell) {
    const mapName = currentCell.map || "overworld";
    const mapCells = Object.values(cells).filter(c => c.map === mapName);
    if (!mapCells.length) return "";
    let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
    const byCoord = {};
    for (const c of mapCells) {
        if (c.x < minX) minX = c.x;
        if (c.x > maxX) maxX = c.x;
        if (c.y < minY) minY = c.y;
        if (c.y > maxY) maxY = c.y;
        byCoord[c.x + "," + c.y] = c;
    }
    const lines = ["MAP: " + mapName + " ([@]=You, [.]=Room)"];
    for (let y = minY; y <= maxY; y++) {
        let row = "";
        let conn = "";
        for (let x = minX; x <= maxX; x++) {
            const c = byCoord[x + "," + y];
            const marker = !c ? "   " : (c.id === currentCell.id ? "[@]" : "[.]");
            const hasE = c && c.exits && (c.exits.E || c.exits.e);
            row += marker + (x < maxX ? (hasE ? "-" : " ") : "");
            if (y < maxY) {
                const hasS = c && c.exits && (c.exits.S || c.exits.s);
                conn += (hasS ? " | " : "   ") + (x < maxX ? " " : "");
            }
        }
        lines.push(row);
        if (y < maxY && conn.trim()) lines.push(conn);
    }
    return lines.join("\n");
}

function renderCellBlock(cells, cell, time, weather) {
    const delta = getDelta(cell.id);
    const desc = (cell.desc && (cell.desc[time] || cell.desc.day || cell.desc.night)) || "";
    const exitsList = Object.entries(cell.exits || {}).map(([d, dest]) => {
        const destName = cells[dest] ? cells[dest].name : dest;
        return d + " -> " + destName + " (" + dest + ")";
    });
    const presentNpcs = [];
    const absentNpcs = [];
    for (const [id, npc] of Object.entries(cell.npcs || {})) {
        const nd = delta.npcs[id] || {};
        const status = String(nd.status || "").toLowerCase();
        const label = npc.name + (npc.role ? " (" + npc.role + ")" : "");
        if (status && DEAD_STATUSES.has(status)) {
            absentNpcs.push(label + " [" + nd.status + (nd.note ? ": " + nd.note : "") + "]");
        } else {
            const noteStr = nd.note ? " | Note: " + nd.note : "";
            presentNpcs.push(label + ": " + (npc.desc || "") + noteStr);
        }
    }
    const objLines = [];
    const mergedObjects = Object.assign({}, cell.objects || {}, delta.objects || {});
    for (const [id, text] of Object.entries(mergedObjects)) {
        objLines.push(id + ": " + text);
    }
    const lines = [
        "[WORLD STATE]",
        "Location: " + cell.name + " (" + cell.id + ") | Time: " + time + " | Weather: " + weather,
        "Description: " + desc,
        "Exits: " + (exitsList.length ? exitsList.join(", ") : "None")
    ];
    const ascii = buildAsciiMap(cells, cell);
    if (ascii) lines.push(ascii);
    if (presentNpcs.length) lines.push("[PRESENT HERE]\n- " + presentNpcs.join("\n- "));
    if (absentNpcs.length) lines.push("[NO LONGER HERE (DO NOT REVIVE)]\n- " + absentNpcs.join("\n- "));
    if (objLines.length) lines.push("[OBJECTS]\n- " + objLines.join("\n- "));
    const flagEntries = Object.entries(delta.flags || {}).map(([k, v]) => k + "=" + JSON.stringify(v));
    if (delta.events.length || flagEntries.length) {
        const changes = [];
        for (const ev of delta.events) changes.push("Event: " + ev);
        if (flagEntries.length) changes.push("Flags: " + flagEntries.join(", "));
        lines.push("[PERSISTENT CHANGES HERE]\n- " + changes.join("\n- "));
    }
    lines.push("[/WORLD STATE]");
    return lines.join("\n");
}

const { cells, bookFound } = loadWorld();
const cellIds = Object.keys(cells);
let loc = context.chat_data.get("mud_loc") || (cells[DEFAULT_LOC] ? DEFAULT_LOC : (cellIds[0] || DEFAULT_LOC));
let prevLoc = context.chat_data.get("mud_prev_loc") || loc;
let time = context.chat_data.get("mud_time") || "day";
let weather = context.chat_data.get("mud_weather") || "clear";

if (context.tool_call && context.tool_call.args) {
    if (!cellIds.length) {
        context.tool_result = "MUD World Engine error: world lorebook '" + BOOK_NAME + "' is not loaded.";
    } else {
        const args = context.tool_call.args;
        const action = String(args.action || "look").toLowerCase().trim();
        const cell = cells[loc] || cells[cellIds[0]];
        if (action === "move") {
            const dir = String(args.dir || "").toUpperCase().trim();
            const destId = cell.exits[dir];
            if (!destId || !cells[destId]) {
                const validDirs = Object.keys(cell.exits || {}).join(", ") || "none";
                context.tool_result = "Cannot move '" + dir + "' from " + cell.name + ". Valid exits: " + validDirs;
            } else {
                context.chat_data.set("mud_prev_loc", cell.id);
                context.chat_data.set("mud_loc", destId);
                context.tool_result = "Moved " + dir + " to " + cells[destId].name + ".\n" + renderCellBlock(cells, cells[destId], time, weather);
            }
        } else if (action === "look") {
            const target = String(args.target || "").trim().toLowerCase();
            if (!target) {
                context.tool_result = renderCellBlock(cells, cell, time, weather);
            } else {
                const delta = getDelta(cell.id);
                const mergedObjs = Object.assign({}, cell.objects || {}, delta.objects || {});
                const objHit = Object.entries(mergedObjs).find(([k]) => k.toLowerCase() === target);
                const npcHit = Object.entries(cell.npcs || {}).find(([k, v]) => k.toLowerCase() === target || (v.name || "").toLowerCase() === target);
                if (objHit) {
                    context.tool_result = "Object [" + objHit[0] + "]: " + objHit[1];
                } else if (npcHit) {
                    const [nid, npc] = npcHit;
                    const nd = delta.npcs[nid] || {};
                    context.tool_result = "NPC [" + npc.name + "]: " + (npc.desc || "") + (nd.status ? " (Status: " + nd.status + ")" : "") + (nd.note ? " Note: " + nd.note : "");
                } else {
                    context.tool_result = "No '" + target + "' found in " + cell.name + ".";
                }
            }
        } else {
            context.tool_result = "Unknown action '" + action + "'. Use action='move' or action='look'.";
        }
    }
} else if (context.response && typeof context.response.content === "string") {
    const tags = context.response_tags || {};
    const movePayloads = Array.isArray(tags.mud_move) ? tags.mud_move : [];
    for (const rawMove of movePayloads) {
        const m = String(rawMove || "").trim();
        if (!m) continue;
        const cur = cells[loc];
        let dest = null;
        if (cells[m]) {
            dest = m;
        } else if (cur && cur.exits && cur.exits[m.toUpperCase()] && cells[cur.exits[m.toUpperCase()]]) {
            dest = cur.exits[m.toUpperCase()];
        }
        if (dest && dest !== loc) {
            prevLoc = loc;
            loc = dest;
            context.chat_data.set("mud_prev_loc", prevLoc);
            context.chat_data.set("mud_loc", loc);
        }
    }
    const timePayloads = Array.isArray(tags.mud_time) ? tags.mud_time : [];
    for (const rawTime of timePayloads) {
        const t = String(rawTime || "").trim();
        if (!t) continue;
        if (t.startsWith("{")) {
            try {
                const parsed = JSON.parse(t);
                if (parsed.time) { time = String(parsed.time); context.chat_data.set("mud_time", time); }
                if (parsed.weather) { weather = String(parsed.weather); context.chat_data.set("mud_weather", weather); }
            } catch (e) {}
        } else {
            const low = t.toLowerCase();
            if (low === "day" || low === "night") {
                time = low;
                context.chat_data.set("mud_time", time);
            } else {
                weather = low;
                context.chat_data.set("mud_weather", weather);
            }
        }
    }
    const deltaPayloads = Array.isArray(tags.mud_delta) ? tags.mud_delta : [];
    if (deltaPayloads.length) {
        const d = getDelta(loc);
        for (const rawDelta of deltaPayloads) {
            const s = String(rawDelta || "").trim();
            if (!s) continue;
            if (s.startsWith("{")) {
                try {
                    const p = JSON.parse(s);
                    if (typeof p.event === "string" && p.event.trim()) d.events.push(p.event.trim());
                    if (Array.isArray(p.events)) p.events.forEach(ev => { if (typeof ev === "string" && ev.trim()) d.events.push(ev.trim()); });
                    if (p.npcs && typeof p.npcs === "object") {
                        for (const [k, v] of Object.entries(p.npcs)) d.npcs[k] = Object.assign({}, d.npcs[k] || {}, v);
                    }
                    if (p.objects && typeof p.objects === "object") Object.assign(d.objects, p.objects);
                    if (p.flags && typeof p.flags === "object") Object.assign(d.flags, p.flags);
                } catch (e) {}
            } else {
                d.events.push(s);
            }
        }
        context.chat_data.set("cell:" + loc, d);
    }
    const imagesEnabled = Boolean(context.chat_data.get("mud_images_enabled"));
    const activeCell = cells[loc];
    if (imagesEnabled && activeCell && activeCell.images) {
        const imgUrl = String(activeCell.images[time + "_" + weather] || activeCell.images[time] || activeCell.images.day || "").trim();
        const lastImg = context.chat_data.get("mud_last_img") || "";
        if (imgUrl && imgUrl !== lastImg) {
            context.response.content = "![" + activeCell.name + "](" + imgUrl + ")\n\n" + context.response.content;
            context.response.modified = true;
            context.chat_data.set("mud_last_img", imgUrl);
        }
    }
} else {
    context.character = context.character || {};
    context.character.scenario = context.character.scenario || "";
    if (context.request && context.request.is_regenerate && prevLoc && cells[prevLoc]) {
        loc = prevLoc;
        context.chat_data.set("mud_loc", loc);
    }
    if (!context.chat_data.get("mud_loc")) context.chat_data.set("mud_loc", loc);
    if (!context.chat_data.get("mud_prev_loc")) context.chat_data.set("mud_prev_loc", prevLoc);
    if (!context.chat_data.get("mud_time")) context.chat_data.set("mud_time", time);
    if (!context.chat_data.get("mud_weather")) context.chat_data.set("mud_weather", weather);
    if (!bookFound || !cellIds.length) {
        context.character.scenario += "\n\n[MUD ENGINE NOTICE]\nLorebook '" + BOOK_NAME + "' was not found or contains no valid cell JSON entries. Import it inactive and ensure it is listed in this cantrip's lorebook_reads.\n[/MUD ENGINE NOTICE]";
    } else {
        const cell = cells[loc] || cells[cellIds[0]];
        const block = renderCellBlock(cells, cell, time, weather);
        const instr = "\n[MUD ENGINE INSTRUCTIONS]\n- Only describe exits, objects, and NPCs listed in [WORLD STATE]. Never revive NPCs in [NO LONGER HERE].\n- To move or inspect mid-turn, call <call:mud_world_engine action=\"move\" dir=\"E\" /> or action=\"look\".\n- To record state changes at the end of your reply (stripped before the user sees them), emit hidden tags:\n  <mud_move>overworld:b1</mud_move> (or direction like E)\n  <mud_time>night</mud_time> (or {\"time\":\"night\",\"weather\":\"rain\"})\n  <mud_delta>{\"event\":\"...\",\"npcs\":{\"bren\":{\"status\":\"departed\"}}}</mud_delta>\n[/MUD ENGINE INSTRUCTIONS]";
        context.character.scenario += "\n\n" + block + instr;
    }
}
